function icon(name,size=20){const paths={play:'<path d="m8 4 13 8-13 8Z"/>',pause:'<path d="M8 4v16M16 4v16"/>',columns:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M10 3v18"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="3"/><path d="M8 7V4h8v3M3 12h18M10 12v3h4v-3"/>',apps:'<rect x="5" y="4" width="14" height="17" rx="2"/><path d="M9 4V2h6v2M9 10h6M9 14h6M9 18h4"/>',message:'<path d="M21 11a8 8 0 0 1-8 8H7l-5 3 2-6a8 8 0 0 1-1-5 9 9 0 0 1 18 0Z"/><path d="M7 10h10M7 14h6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>',resume:'<path d="M14 2H5v20h14V7l-5-5Zm0 0v5h5M8 11h8M8 15h8M8 18h5"/>',spark:'<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3ZM20 2v4M18 4h4"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h8a4 4 0 0 1 0 8H9a4 4 0 0 0 0 8h8"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',save:'<path d="M6 3h12v19l-6-4-6 4Z"/>',send:'<path d="m3 3 19 9L3 21l4-9-4-9Zm4 9h15"/>',plus:'<path d="M12 4v16M4 12h16"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',accountSettings:'<circle cx="9" cy="7" r="3.5"/><path d="M2.5 20v-1.5A6.5 6.5 0 0 1 9 12h1"/><circle cx="17.5" cy="17" r="2.5"/><path d="M17.5 12.8v1.2m0 6v1.2m-4.2-4.2h1.2m6 0h1.2m-7.2-3 0.9.9m4.2 4.2.9.9m0-6-.9.9m-4.2 4.2-.9.9"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',archive:'<rect x="3" y="3" width="18" height="5" rx="1"/><path d="M5 8v13h14V8M9 12h6"/>',link:'<path d="M10 13a5 5 0 0 0 7 .5l3-3a5 5 0 0 0-7-7l-2 2M14 11a5 5 0 0 0-7-.5l-3 3a5 5 0 0 0 7 7l2-2"/>',check:'<path d="m5 12 4 4L20 5"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.briefcase}</svg>`}
function workspaceNav(page){const org=isOrganizationAccount(),links=org?[['organization','briefcase','Hiring portal'],['messages','message','Messages']]:[['overview','apps','Overview'],['explore','briefcase','Find work'],['projects','save','My work'],['recommend','spark','Project ideas'],['messages','message','Messages'],['resume','resume','My resume']];const item=([route,symbol,label])=>{const active=page===route||(route==='settings'&&page==='profile')||(route==='resume'&&page.startsWith('resume/'))||(route==='explore'&&page.startsWith('project/'))||(route==='projects'&&page.startsWith('recommend/saved/'))||(route==='recommend'&&page.startsWith('recommend/')&&!page.startsWith('recommend/saved/'));return `<a class="nav-link ${active?'active':''}" data-nav="${route}" href="#${route}" ${active?'aria-current="page"':''}>${icon(symbol,20)}<span>${label}</span>${route==='messages'&&unreadCount()?`<b class="nav-unread">${unreadCount()}</b>`:''}</a>`};return `<span class="nav-caption">${org?'HIRING WORKSPACE':'WORKSPACE'}</span>${links.map(item).join('')}${item(['settings','accountSettings','Account settings'])}`}

function nextSteps(){return `<div class="next-steps"><a href="#explore">${icon('search')}<div><b>1. Find your project</b><small>Browse paid opportunities</small></div></a><a href="#resume">${icon('eye')}<div><b>2. Check your fit</b><small>See your resume evidence</small></div></a><a href="#projects">${icon('send')}<div><b>3. Make your move</b><small>Apply & track your work</small></div></a></div>`}
function workspaceSettings(){if(isOrganizationAccount())return title('Organization account settings','Manage your hiring account and sign-in settings.')+accountPanel();const sideContent=(typeof Account!=='undefined'?accountPanel():'')+`<section class="panel wide-panel settings-panel"><h2>Workspace data</h2><p>Your profile, resume, saved projects, and application drafts are saved to your account. Messages use private conversations between signed-in members when messaging is enabled. Sample marketplace applications remain drafts; organization applications are submitted to the named employer. Career-tool previews are not live outreach services. There is no live presence.</p><h3>Nextwork brand assets</h3><p>The uploaded Nextwork icon and original wordmark lockups.</p><div class="brand-downloads"><a class="outline" href="assets/brand/nextwork-icon.png" download>App icon ↓</a><a class="outline" href="assets/brand/nextwork-wordmark-primary.png" download>Primary lockup ↓</a><a class="outline" href="assets/brand/nextwork-wordmark-reversed.png" download>Reversed lockup ↓</a></div><h3>My resume</h3><p>Instant matching runs locally. Optional Gemini analysis uses the configured free-tier key only after you explicitly consent.</p><a class="outline" href="#resume">Open my resume →</a></section>`;return title('Account settings','Manage your profile, sign-in, and workspace data.')+profile(true,sideContent)}
function tidyWorkspace(){const area=$('#app');area.querySelectorAll('[data-workspace-note]').forEach(x=>x.remove());area.querySelectorAll('.notice,.trust').forEach(el=>{if(/demo|sample opportunity|sample marketplace|stored locally|not a signed-in|not shared with|does not contact|not sent to|saved locally|saved on this device/i.test(el.textContent))el.remove()});area.querySelectorAll('.tag').forEach(el=>{if(/sample marketplace listing|application saved locally/i.test(el.textContent))el.textContent=el.textContent.includes('Application')?'Application saved':'Project'});}

function bookmarkIcon(filled=false){return `<svg class="bookmark-symbol" width="20" height="20" viewBox="0 0 24 24" fill="${filled?'currentColor':'none'}" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 3.5h10a1 1 0 0 1 1 1v16l-6-4-6 4v-16a1 1 0 0 1 1-1Z"/></svg>`}
